      "sourcePort": "output",
      "targetNodeId": "triageAgent1",
      "targetPort": "input"
    },
    {
      "id": "edge-agent-to-end",
      "sourceNodeId": "triageAgent1",
      "sourcePort": "success",
      "targetNodeId": "end1",
      "targetPort": "input"
    }
  ],
  "definitions": [
    {
      "nodeType": "core.trigger.manual",
      "version": "1.0",
